fd169c5a1786b2f0.sql:
SELECT COUNT(*) 
FROM transaction 
WHERE EXTRACT(MONTH FROM transaction.trans_time) = 6 AND trans_type = 'DIMENSION' AND channel_receiver = 'DIMENSION';

49598560cfff9b4a.sql:
SELECT SUM(amount_transfer) AS total_amount
FROM transaction
WHERE trans_time >= DATE_SUB(CURRENT_DATE, INTERVAL 7 DAY) AND amount_transfer > 2000000;
